namespace ShoujoKagekiAijoKaren.src.Core.Models.Cards.neutral;

/// <summary>
/// 最后的台词 - 如果约定牌堆之外只有这张牌，对所有敌人造成伤害
/// </summary>
public sealed class KarenLastWord : KarenBaseCardModel
{
    public KarenLastWord() : base(0, CardType.Attack, CardRarity.Rare, TargetType.AllEnemies) { }

    protected override IEnumerable<DynamicVar> CanonicalVars => [new DamageVar(999, ValueProp.Move)];

    protected override IEnumerable<IHoverTip> ExtraHoverTips =>
        [new HoverTip(
            new LocString("cards", "KAREN_LAST_WORD.tip.title"),
            new LocString("cards", "KAREN_LAST_WORD.tip").GetFormattedText()
        )];

    protected override async Task OnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)
    {
        if (!Condition(base.Owner, this)) { return; }
        if (CombatState == null) return;

        // Cmd.Wait skips Instant/non-interactive play; skip the cutscene with it.
        if (!NonInteractiveMode.IsActive && SaveManager.Instance.PrefsSave.FastMode != FastModeType.Instant)
        {
            bool isLocalOwner = LocalContext.IsMe(Owner);
            bool playedVideo = false;
            CombatBgmReplacementManager.StopForCutscene();
            KarenAudioManager.PlaySfx(KarenSfx.LastWord, volume: 1f);
            if (isLocalOwner)
            {
                playedVideo = NKarenLastWordVideoVfx.Play(Owner);
                if (!playedVideo)
                    NKarenLastWordVfx.Play(Owner);
            }
            else
            {
                NKarenLastWordVfx.Play(Owner);
            }

            bool shouldWaitForVideoSequence = playedVideo || (!isLocalOwner && NKarenLastWordVideoVfx.HasVideo());
            await Cmd.Wait(shouldWaitForVideoSequence
                ? NKarenLastWordVideoVfx.VideoSequenceSeconds
                : NKarenLastWordVideoVfx.LettersOnlySequenceSeconds);
        }

        await DamageCmd.Attack(base.DynamicVars.Damage.BaseValue).FromPlayedCard(this, cardPlay).TargetingAllOpponents(CombatState)
            //.WithHitFx(VfxCmd.slashPath)
            .Execute(choiceContext);
    }

    protected override bool IsPlayable => Condition(base.Owner, this);

    // 抽牌堆，弃牌堆，手牌中，最多只有这张牌
    private static bool Condition(Player player, CardModel card)
    {
        var hand = PileType.Hand.GetPile(player);
        if (hand.Cards.Any(c => c != card)) return false;

        var discardPile = PileType.Discard.GetPile(player);
        if (discardPile.Cards.Any(c => c != card)) return false;

        if(!PromisePileManager.IsVoidMode(player)) // 空虚模式下，抽牌堆算约定牌堆，不用判断抽牌堆
        {
            var drawPile = PileType.Draw.GetPile(player);
            if (drawPile.Cards.Any(c => c != card)) return false;
        }

        return true;
    }

    protected override void OnUpgrade()
    {
        DynamicVars.Damage.UpgradeValueBy(9000m);
    }
}
